    /// <summary>
    /// Validates the record before writing.
    /// </summary>
    /// <returns>True, if valid; otherwisem false.</returns>
    public boolean validateWrite()
    {
        boolean ret;

        ret = next validateWrite();

        if (ret)
        {
            ret = this.metValidateStatus();
        }

        return ret;
    }

    /// <summary>
    /// CB232_AutoSettingItemStockStatus.
    /// Validates if status is already assigned to another product lifecycle state record.
    /// </summary>
    /// <returns>True, if valid; otherwise, false.</returns>
    private boolean metValidateStatus()
    {
        EcoResProductLifecycleState productLifeCycleState;
        EcoResProductLifecycleState productLifeCycleStateOrig;
        boolean                     ret;

        ret = true;

        productLifeCycleStateOrig = this.orig();

        if (this.METStatus != productLifeCycleStateOrig.METStatus
         && this.METStatus != METEcoResProductLifecycleStateStatus::None)
        {
            select firstonly RecId from productLifeCycleState
                where productLifeCycleState.METStatus == this.METStatus
                &&    productLifeCycleState.RecId     != this.RecId;

            if (productLifeCycleState.RecId)
            {
                ret = checkFailed("@MET:METProductLifecycleStateStatusAssignedError");
            }
        }

        return ret;
    }
